//! Application exit owns the deadline; no task-table lock spans process I/O.
use super::retained_session::StartRegistry;
use std::{sync::Arc, time::Duration};

use super::{retained_session, task_bridge::ForwarderGuard, CodexAppServerSession};

use tauri::Manager;

static EXIT: super::exit_gate::ExitGate = super::exit_gate::ExitGate::new();

pub fn ready_to_exit() -> bool {
    EXIT.ready()
}

/// Both tray Quit and runtime ExitRequested use this entry. The second event
/// generated by app.exit is allowed through only after cleanup has finished.
pub fn request_exit(app: &tauri::AppHandle, code: i32) {
    if !EXIT.begin() {
        return;
    }
    let manager = app.state::<crate::TaskManager>();
    let plan = ShutdownPlan::begin(&manager, retained_session::start_registry());
    super::prediction::invalidate_all_for_exit(app);
    let app = app.clone();
    tauri::async_runtime::spawn(async move {
        let pty_app = app.clone();
        let pty = tokio::task::spawn_blocking(move || {
            pty_app.state::<crate::TaskManager>().kill_all_children();
        });
        let manager = app.state::<crate::TaskManager>();
        let (structured, pty) = tokio::join!(
            plan.finish(&manager, Duration::from_secs(6)),
            tokio::time::timeout(Duration::from_secs(3), pty),
        );
        if let Err(error) = structured {
            eprintln!("[codex_appserver] exit: {error}");
        }
        if !matches!(pty, Ok(Ok(()))) {
            eprintln!("[nezha] PTY exit cleanup did not finish before deadline");
        }
        EXIT.finish();
        app.exit(code);
    });
}

struct ShutdownPlan {
    starts: Arc<StartRegistry>,
    pending: Vec<ForwarderGuard>,
    sessions: Vec<(String, u64, Arc<CodexAppServerSession>)>,
}

impl ShutdownPlan {
    fn begin(manager: &crate::TaskManager, starts: Arc<StartRegistry>) -> Self {
        let pending = starts.begin_shutdown();
        let sessions = manager
            .codex_appserver_sessions
            .lock()
            .iter_mut()
            .map(|(task, entry)| {
                entry.guard.cancel();
                entry.lifecycle.begin_close();
                (
                    task.clone(),
                    entry.lifecycle.generation(),
                    entry.session.clone(),
                )
            })
            .collect();
        Self {
            starts,
            pending,
            sessions,
        }
    }

    async fn finish(self, manager: &crate::TaskManager, budget: Duration) -> Result<(), String> {
        let closes =
            futures_util::future::join_all(self.sessions.iter().map(|(task, generation, _)| {
                retained_session::close_owned(manager, task, *generation)
            }));
        let graceful = tokio::time::timeout(budget, async {
            let (results, ()) = tokio::join!(closes, self.starts.drained());
            results.into_iter().collect::<Result<Vec<_>, _>>()?;
            let pending: Vec<_> = self
                .pending
                .iter()
                .filter_map(ForwarderGuard::startup_session)
                .collect();
            futures_util::future::join_all(
                pending
                    .iter()
                    .map(CodexAppServerSession::shutdown_confirmed),
            )
            .await
            .into_iter()
            .collect::<Result<Vec<_>, String>>()
        })
        .await;
        if matches!(graceful, Ok(Ok(_))) {
            return Ok(());
        }

        // Only handles captured from our ownership table/start reservations.
        // A cancelled startup may publish its core after begin(), hence read the
        // shared weak handle here instead of taking a second task-owner snapshot.
        let mut sessions: Vec<_> = self
            .sessions
            .iter()
            .map(|(_, _, session)| session.clone())
            .collect();
        sessions.extend(
            self.pending
                .iter()
                .filter_map(ForwarderGuard::startup_session)
                .map(Arc::new),
        );
        let forced = tokio::time::timeout(
            Duration::from_secs(2),
            futures_util::future::join_all(sessions.iter().map(|session| force_reap(session))),
        )
        .await;
        if matches!(&forced, Ok(results) if results.iter().all(Result::is_ok)) {
            let mut table = manager.codex_appserver_sessions.lock();
            for (task, generation, _) in &self.sessions {
                if table
                    .get(task)
                    .is_some_and(|entry| entry.lifecycle.is_owner(*generation))
                {
                    table.remove(task);
                }
            }
        }
        match forced {
            Ok(results) => {
                for result in results {
                    result?;
                }
                Err(
                    "application shutdown exceeded graceful deadline; owned processes reaped"
                        .into(),
                )
            }
            Err(_) => Err("application shutdown force-reap deadline exceeded".into()),
        }
    }
}

async fn force_reap(session: &CodexAppServerSession) -> Result<(), String> {
    let mut child = session.core.child.lock().await;
    if child
        .try_wait()
        .map_err(|error| error.to_string())?
        .is_none()
    {
        child.start_kill().map_err(|error| error.to_string())?;
        child.wait().await.map_err(|error| error.to_string())?;
    }
    drop(child);
    if let Ok(mut confirmation) = session.core.shutdown_result.try_lock() {
        *confirmation = Some(Ok(()));
    }
    Ok(())
}

pub async fn shutdown_sessions(
    manager: &crate::TaskManager,
    starts: &Arc<StartRegistry>,
    budget: Duration,
) -> Result<(), String> {
    ShutdownPlan::begin(manager, starts.clone())
        .finish(manager, budget)
        .await
}

#[cfg(test)]
mod tests {
    use super::super::{
        retained_session, session_lifecycle::Lifecycle, task_bridge::ForwarderGuard,
        CodexAppServerSession, SessionCore,
    };
    use super::*;

    #[tokio::test]
    async fn exit_deadline_forces_only_its_pending_process_and_returns() {
        let manager = crate::TaskManager::empty_for_test();
        let starts = Arc::new(StartRegistry::default());
        let pending = starts.begin("blocked-start").unwrap();
        #[cfg(windows)]
        let mut command = {
            let mut command = tokio::process::Command::new("powershell");
            command.args(["-NoProfile", "-Command", "Start-Sleep -Seconds 60"]);
            command
        };
        #[cfg(not(windows))]
        let mut command = {
            let mut command = tokio::process::Command::new("sleep");
            command.arg("60");
            command
        };
        crate::subprocess::configure_background_tokio_command(&mut command);
        let session = CodexAppServerSession {
            core: SessionCore::test_core_with_command(command),
        };
        pending.token().register_startup_core(&session.core);
        let started = std::time::Instant::now();
        assert!(
            shutdown_sessions(&manager, &starts, Duration::from_millis(10))
                .await
                .is_err()
        );
        assert!(started.elapsed() < Duration::from_secs(3));
        assert!(pending.check().is_err());
        tokio::time::timeout(Duration::from_millis(100), session.shutdown_confirmed())
            .await
            .expect("exit deadline left an owned startup process alive")
            .unwrap();
    }

    #[tokio::test]
    async fn exit_reaps_running_and_retained_sessions_and_drains_pending_starts() {
        let manager = crate::TaskManager::empty_for_test();
        let starts = Arc::new(StartRegistry::default());
        let pending = starts.begin("pending").unwrap();
        let pending_worker = tokio::spawn(async move {
            pending.cancelled().await;
            assert!(pending.check().is_err());
        });
        let mut sessions = Vec::new();
        for task in ["running", "retained"] {
            let guard = ForwarderGuard::new(Lifecycle::running().generation());
            let session = Arc::new(CodexAppServerSession {
                core: SessionCore::test_core(),
            });
            retained_session::activate(&manager, task, &guard, session.clone()).unwrap();
            if task == "retained" {
                retained_session::set_retention(&manager, task, guard.generation(), true);
                assert!(retained_session::completed(
                    &manager,
                    task,
                    guard.generation(),
                    "turn",
                    std::time::Instant::now()
                )
                .is_some());
            }
            sessions.push((task, guard, session));
        }
        tokio::time::timeout(
            Duration::from_secs(2),
            shutdown_sessions(&manager, &starts, Duration::from_secs(1)),
        )
        .await
        .unwrap()
        .unwrap();
        for (task, guard, session) in sessions {
            assert!(
                !retained_session::owns(&manager, task, guard.generation()),
                "exit left session installed"
            );
            assert!(guard.is_cancelled());
            // The session API confirms process reaping, not merely removal from the table.
            tokio::time::timeout(Duration::from_millis(100), session.shutdown_confirmed())
                .await
                .unwrap()
                .unwrap();
        }
        pending_worker.await.unwrap();
        assert!(starts.begin("after-exit").is_err());
        shutdown_sessions(&manager, &starts, Duration::from_millis(100))
            .await
            .unwrap();
    }
}
